package com.finanscore.report.presentation;import com.finanscore.report.infrastructure.*;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/v1/reports") public class ReportController{private final ReportRepository repo;private final MinioReportStorage storage;public ReportController(ReportRepository r,MinioReportStorage s){repo=r;storage=s;}@GetMapping("/{id}/download")public ResponseEntity<InputStreamResource> download(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id)throws Exception{var r=repo.findById(id).orElseThrow();if(!r.userId.equals(Long.valueOf(jwt.getSubject())))throw new SecurityException("Reporte no pertenece al usuario");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=report-"+r.requestId+".pdf").contentType(MediaType.APPLICATION_PDF).body(new InputStreamResource(storage.get(r.objectKey)));}}